// __PROJECT__: a starter tweak written in Logos.
// %hook picks a class, %orig calls the original code, %end closes the hook.
#import <UIKit/UIKit.h>

%hook UIViewController

- (void)viewDidAppear:(BOOL)animated {
    %orig;
    NSLog(@"[__PROJECT__] %@ appeared", NSStringFromClass([self class]));
}

%end

%ctor {
    NSLog(@"[__PROJECT__] loaded into %@", [[NSBundle mainBundle] bundleIdentifier]);
}
